"use client";
/* Plane, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Plane(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("plane"); }, []);
  return React.createElement("piix-pal", { "pal": "plane", ...piixAttrs(props) });
}

export default Plane;
